import os
import torch


class Config:
    """
    Configuration for the Ventilator Pressure Prediction task.
    Implements the 'Strict-Identity Physics-Injected Composite Network' strategy.
    """

    # ==========================================
    # Path Configuration
    # ==========================================
    INPUT_DIR = "./metadata"
    RAW_DATA_DIR = "./input"

    # Metadata paths (generated by previous steps)
    TRAIN_PATH = os.path.join(INPUT_DIR, "train.csv")
    VAL_PATH = os.path.join(INPUT_DIR, "val.csv")
    TEST_PATH = os.path.join(INPUT_DIR, "test.csv")
    SAMPLE_SUBMISSION_PATH = os.path.join(RAW_DATA_DIR, "sample_submission.csv")

    # Working directories
    WORK_DIR = "./working/idea_19"
    CACHE_DIR = os.path.join(WORK_DIR, "cache")
    SUBMISSION_DIR = "./submission"

    # Output paths
    MODEL_PATH = os.path.join(WORK_DIR, "model.pth")
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Reproducibility & Hardware
    # ==========================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4

    # ==========================================
    # Data Parameters
    # ==========================================
    # Set to True to run on a small subset for debugging
    DEBUG = False
    DEBUG_BREATHS = 1000

    # ==========================================
    # Feature Engineering Configuration
    # ==========================================
    # Physics fidelity settings
    USE_LAGS = True
    LAGS = [1, 2, 3, 4]

    USE_DIFFS = True
    DIFF_ORDERS = [1, 2]  # First and second differences

    USE_PHYSICS = True  # Enable volume calc and interactions (u_in*R, vol/C)

    # Scaling strategy
    # u_out is binary and strictly excluded from scaling
    # R, C are treated as continuous
    ROBUST_SCALER_QUANTILE_RANGE = (5.0, 95.0)

    # ==========================================
    # Model Architecture
    # ==========================================
    # Stem (Multi-Scale CNN)
    STEM_KERNELS = [3, 5, 7]

    # Backbone
    D_MODEL = 512
    N_BLOCKS = 4

    # Composite Block Internals
    # LSTM hidden is 256 per direction => 512 total, matching D_MODEL for strict identity
    LSTM_HIDDEN = 256
    EXPANSION_FACTOR = 2  # FFN expansion -> 1024
    DROPOUT = 0.1

    # Auxiliary Head
    AUX_HEAD_IDX = 1  # 0-indexed, output of 2nd block
    AUX_WEIGHT = 0.3

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    EPOCHS = 35
    BATCH_SIZE = 512

    # Optimization
    OPTIMIZER = "AdamW"
    LR_MAX = 1e-3
    WEIGHT_DECAY = 1e-2

    # Scheduler (OneCycleLR)
    PCT_START = 0.3
    DIV_FACTOR = 25.0
    FINAL_DIV_FACTOR = 1e4

    # Gradient Clipping (Strict)
    GRAD_CLIP = 1.0

    # Loss
    LOSS_NAME = "MaskedL1"  # Custom weighted masked L1

    @classmethod
    def setup(cls):
        """
        Initialize the working directories.
        """
        os.makedirs(cls.WORK_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def to_dict(cls):
        """
        Return configuration as a dictionary.
        """
        return {
            k: v
            for k, v in cls.__dict__.items()
            if not k.startswith("__") and not callable(v)
        }
